cat > /tmp/<path> <<'EOF'
import re

def parse(path):
    ins=[]
    for raw in open(path):
        line=raw.split(';',1)[0].strip()
        if not line: continue
        parts=line.split()
        ins.append((parts[0], parts[1:]))
    return ins

regs={'a':0,'b':0,'c':0,'d':0}

def val(tok):
    if tok in regs: return regs[tok]
    return int(tok)

def run(ins, limit=100_000_000, trace=False):
    pc=0; count=0; outputs=[]
    while 0<=pc<len(ins):
        op,args=ins[pc]
        count+=1
        nxt=pc+1
        if op=='set':
            r,x=args
            regs[r]=val(x)%65536
        elif op=='add':
            r,x=args
            regs[r]=(regs[r]+val(x))%65536
        elif op=='mul':
            r,x=args
            regs[r]=(regs[r]*val(x))%65536
        elif op=='mod':
            r,x=args
            v=val(x)
            if v>0: regs[r]=regs[r]%v
        elif op=='dec':
            r=args[0]
            regs[r]=max(0,regs[r]-1)
        elif op=='jnz':
            x,k=args
            if val(x)!=0:
                nxt=pc+val(k)
        elif op=='skp':
            x,y=args
            if val(x)<val(y):
                nxt=pc+2
        elif op=='out':
            outputs.append(val(args[0]))
        else:
            raise ValueError(op)
        if trace: print(pc,op,args,dict(regs),outputs[-1] if outputs else None)
        pc=nxt
        if count>limit: raise RuntimeError('limit')
    return count,outputs

ins=parse('/tmp/<path>')
for i,x in enumerate(ins): print(i,x)
count,outputs=run(ins)
print('count',count)
print('num outputs',len(outputs))
print('sum',sum(outputs))
print('first 20',outputs[:20])
print('last 20',outputs[-20:])
