cat > /tmp/<path> <<'EOF'
# Independent re-implementation, line-by-line, recording stats.
import re

src = open('/tmp/<path>').read().splitlines()
prog = []
for line in src:
    line = re.sub(r';.*', '', line).strip()
    if line:
        prog.append(line.split())

R = {'a': 0, 'b': 0, 'c': 0, 'd': 0}
M = 65536

def get(t):
    return R[t] if t in R else int(t)

pc = 0
executed = 0
outs = []
iters = 0
noskip = 0
entered_loop = False
while 0 <= pc < len(prog):
    toks = prog[pc]
    op = toks[0]
    executed += 1
    npc = pc + 1
    if op == 'set':
        R[toks[1]] = get(toks[2]) % M
    elif op == 'add':
        R[toks[1]] = (R[toks[1]] + get(toks[2])) % M
    elif op == 'mul':
        R[toks[1]] = (R[toks[1]] * get(toks[2])) % M
    elif op == 'mod':
        d = get(toks[2])
        if d > 0:
            R[toks[1]] %= d
    elif op == 'dec':
        R[toks[1]] = max(0, R[toks[1]] - 1)
    elif op == 'jnz':
        if get(toks[1]) != 0:
            npc = pc + get(toks[2])
    elif op == 'skp':
        if get(toks[1]) < get(toks[2]):
            npc = pc + 2
    elif op == 'out':
        outs.append(get(toks[1]))
    else:
        raise SystemExit('bad op ' + op)
    if pc == 4:
        iters += 1
        entered_loop = True
        if not (R['a'] < 500):
            pass
    if pc == 8 and not (R['a'] < 500):
        noskip += 1
    pc = npc

print('executed', executed)
print('loop entries', iters)
print('noskip', noskip)
print('outputs', len(outs))
print('sum', sum(outs))
print('d', R['d'], 'a', R['a'], 'b', R['b'], 'c', R['c'])
print('sum first 198', sum(outs[:198]), 'tail', outs[198:])
